-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.derive_member_attributes(p_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare
  a jsonb; ap jsonb; v_name text;
  v_city text; v_state text; v_country text;
  v_rev numeric; v_band text; v_bd date; v_age int; v_under30 boolean; v_ageband text;
  v_cats text[]; v_model text[]; v_mix text[] := '{}';
  v_sku numeric; v_brands numeric; v_started int; v_title text; v_exp text;
  v_niche text; v_fun text; v_tiktok boolean; v_status text;
  prov jsonb := '{}'::jsonb;
  card text; answers text; v_submitted timestamptz;
  ch record;
begin
  select at_fields, application into a, ap from digest.member_profiles where at_member_id = p_id;
  if a is null and ap is null then return; end if;
  a := coalesce(a, '{}'::jsonb); ap := coalesce(ap, '{}'::jsonb);
  v_name := coalesce(nullif(a->>'Full Name',''), nullif(ap->>'Full Name',''));
  v_status := a->>'AT Database Status';

  if coalesce(trim(a->>'City'),'') != '' then v_city := digest.place_city(trim(a->>'City')); prov := prov || '{"city":"at:City"}';
  elsif coalesce(trim(ap->>'City'),'') != '' then v_city := digest.place_city(trim(ap->>'City')); prov := prov || '{"city":"app:City"}'; end if;
  if coalesce(trim(a->>'State'),'') != '' then v_state := digest.attr_state(a->>'State'); prov := prov || '{"state":"at:State"}';
  elsif coalesce(trim(ap->>'State'),'') != '' then v_state := digest.attr_state(ap->>'State'); prov := prov || '{"state":"app:State"}'; end if;
  if coalesce(a->>'Country','') != '' then v_country := a->>'Country'; prov := prov || '{"country":"at:Country"}'; end if;

  v_rev := digest.attr_num(a->>'Most Recent Revenue');
  if v_rev is not null then prov := prov || '{"rev_band":"at:Most Recent Revenue"}';
  else
    v_rev := coalesce(digest.attr_num(ap->>'Most Recent Revenue'), digest.attr_num(ap->>'Total TTM Revenue'));
    if v_rev is not null then prov := prov || '{"rev_band":"app:revenue"}'; end if;
  end if;
  if v_rev is null or v_rev < 100000 then v_band := null;
  elsif v_rev >= 20000000 then v_band := '20M+';
  elsif v_rev >= 10000000 then v_band := '10-20M';
  elsif v_rev >= 5000000 then v_band := '5-10M';
  else v_band := '1-5M'; end if;

  begin
    v_bd := coalesce(nullif(a->>'Birthdate','')::date, nullif(ap->>'Birthdate','')::date);
  exception when others then v_bd := null; end;
  if v_bd is not null then
    v_age := date_part('year', age(v_bd))::int;
    if v_age between 10 and 100 then
      v_under30 := v_age < 30;
      v_ageband := case when v_age < 30 then '20s' when v_age < 40 then '30s'
                        when v_age < 50 then '40s' else '50+' end;
      prov := prov || '{"age":"birthdate"}';
    end if;
  end if;

  v_cats := digest.attr_list(a->'Category');
  v_model := digest.attr_list(a->'Business Model');
  for ch in select * from (values
    ('Amazon US & % of Revenue', 'Amazon US'),
    ('Amazon Canada & % of Revenue', 'Amazon Canada'),
    ('Amazon EU & % of Revenue', 'Amazon EU'),
    ('Other Amazon Marketplaces & % of Revenue', 'Other Amazon'),
    ('Own Website & % of Revenue', 'DTC/Own Website'),
    ('Walmart.com & % of Revenue', 'Walmart'),
    ('Wayfair/Overstock/Target & % of Revenue', 'Wayfair/Overstock/Target'),
    ('Wholesale (Big Box/Large Client) & % of Revenue - per census', 'Wholesale (Big Box)'),
    ('Wholesale (Independent/Mom & Pop) & % of Revenue', 'Wholesale (Independent)')
  ) c(f, name)
  loop
    if coalesce(digest.attr_num(a->>ch.f), 0) > 0 then v_mix := v_mix || ch.name; end if;
  end loop;

  v_sku := coalesce(digest.attr_num(a->>'SKU Count - per census/application'), digest.attr_num(ap->>'# of Products'));
  v_brands := coalesce(digest.attr_num(a->>'How many brands do you currently have?'), digest.attr_num(ap->>'How many brands do you currently have?'));
  v_started := case when digest.attr_num(coalesce(nullif(ap->>'Started Selling',''), a->>'Started Selling')) between 1980 and 2026
                    then digest.attr_num(coalesce(nullif(ap->>'Started Selling',''), a->>'Started Selling'))::int end;
  v_title := digest.attr_title(ap->>'Formal Title');
  v_exp := coalesce(digest.attr_text(a, 'Area of Expertise'), digest.attr_text(ap, 'Area of Expertise'));
  v_niche := coalesce(digest.attr_text(a, 'Main Niche'), digest.attr_text(ap, 'Main Niche'));
  v_fun := coalesce(digest.attr_text(a, 'Interesting / Fun fact'), digest.attr_text(ap, 'Interesting/Fun Fact'));
  v_tiktok := coalesce(a->>'TikTok Presence (Onboarding)','') ilike 'yes%';

  insert into digest.member_attributes as ma
    (at_member_id, full_name, membership_status, city, state, country, rev_band, under_30, age_band,
     categories, sells_supplements, business_model, channel_mix, sku_count, large_sku,
     brands_count, started_year, title, expertise, main_niche, fun_fact, tiktok_seller, provenance, refreshed_at)
  values
    (p_id, v_name, v_status, v_city, v_state, v_country, v_band, v_under30, v_ageband,
     v_cats, exists (select 1 from unnest(v_cats) c where c ilike '%supplements (consumables)%'),
     v_model, v_mix, v_sku::int, coalesce(v_sku, 0) >= 1000,
     v_brands::int, v_started, v_title, v_exp, v_niche, v_fun, v_tiktok, prov, now())
  on conflict (at_member_id) do update set
    full_name = excluded.full_name, membership_status = excluded.membership_status,
    city = excluded.city, state = excluded.state, country = excluded.country,
    rev_band = excluded.rev_band, under_30 = excluded.under_30, age_band = excluded.age_band,
    categories = excluded.categories, sells_supplements = excluded.sells_supplements,
    business_model = excluded.business_model, channel_mix = excluded.channel_mix,
    sku_count = excluded.sku_count, large_sku = excluded.large_sku,
    brands_count = excluded.brands_count, started_year = excluded.started_year,
    title = excluded.title, expertise = excluded.expertise, main_niche = excluded.main_niche,
    fun_fact = excluded.fun_fact, tiktok_seller = excluded.tiktok_seller,
    provenance = excluded.provenance, refreshed_at = now()
  where ma.full_name is distinct from excluded.full_name
     or ma.membership_status is distinct from excluded.membership_status
     or ma.city is distinct from excluded.city
     or ma.state is distinct from excluded.state
     or ma.country is distinct from excluded.country
     or ma.rev_band is distinct from excluded.rev_band
     or ma.under_30 is distinct from excluded.under_30
     or ma.age_band is distinct from excluded.age_band
     or ma.categories is distinct from excluded.categories
     or ma.sells_supplements is distinct from excluded.sells_supplements
     or ma.business_model is distinct from excluded.business_model
     or ma.channel_mix is distinct from excluded.channel_mix
     or ma.sku_count is distinct from excluded.sku_count
     or ma.large_sku is distinct from excluded.large_sku
     or ma.brands_count is distinct from excluded.brands_count
     or ma.started_year is distinct from excluded.started_year
     or ma.title is distinct from excluded.title
     or ma.expertise is distinct from excluded.expertise
     or ma.main_niche is distinct from excluded.main_niche
     or ma.fun_fact is distinct from excluded.fun_fact
     or ma.tiktok_seller is distinct from excluded.tiktok_seller
     or ma.provenance is distinct from excluded.provenance;

  card := concat_ws(chr(10),
    case when v_name is not null then 'Name: ' || v_name end,
    case when v_city is not null or v_state is not null or v_country is not null
         then 'Location: ' || concat_ws(', ', v_city, v_state, v_country) end,
    case when v_title is not null then 'Title: ' || v_title end,
    case when cardinality(v_cats) > 0 then 'Categories: ' || array_to_string(v_cats, ', ') end,
    case when v_niche is not null then 'Main niche: ' || v_niche end,
    case when cardinality(v_model) > 0 then 'Business model: ' || array_to_string(v_model, ', ') end,
    case when cardinality(v_mix) > 0 then 'Sells on: ' || array_to_string(v_mix, ', ') end,
    case when v_started is not null then 'Selling since: ' || v_started end,
    case when v_exp is not null then 'Expertise: ' || v_exp end,
    case when v_fun is not null then 'Fun fact: ' || v_fun end);

  select string_agg('Q: ' || x.q || chr(10) || 'A: ' || x.av, chr(10) || chr(10) order by x.q)
    into answers
  from (
    select q,
      case when lower(coalesce(digest.attr_text(ap, q), '')) = 'true' then 'Yes'
           when lower(coalesce(digest.attr_text(ap, q), '')) = 'false' then 'No'
           else digest.attr_text(ap, q) end as av
    from unnest(array[
      'What made you want to apply for MDS?','Motivation to join MDS','Biggest Challenge','Biggest constraint',
      'Competitive Advantage','Plans for next year','What are your plans for your brand for next year?','Goals',
      'Worked Best For You','Service Provider Big Impact','Work experience prior to selling on Amazon',
      'Knowledge bases','Confidence heading next 12 months','Growth posture','how you teach, coach, or lead',
      '# of Products','How many brands do you currently have?','Other Places Selling','(NEW) Amazon Marketplaces',
      '(NEW) Other Sales Channels','sell on other marketplaces?','Physical retailers','Country of Taxation',
      'What is the name of your brand/company?','Amazon Brand Storefront','Website/Link','(NEW) DTC / Shopify Link',
      '(NEW) TikTok Shop Link','Name of Company/Vendor',
      'Sell Brand? ','Sold a business','Bought a business','Acquiring Ecom Business?',
      'purchased or sold an e-com business?','Roll Up Strategy',
      'Name of Business Partner or Current Member','Partner Associate of','Business Partner/Employee',
      'Who referred?','were you referred?',
      'What types of events would you be most excited to join locally?',
      'How far would you be willing to travel for a regional MDS event?',
      'How often would you ideally attend local or regional events?',
      'What’s one event idea or experience you’d love to see MDS host in your area?  Be as specific as you like.',
      'Would you want to bring someone to some of these events?',
      'What types of socials or team activities do you enjoy most?',
      'What’s the main thing you’d hope to get out of local MDS events?'
    ]) q
  ) x
  where x.av is not null and x.av != '';

  begin
    v_submitted := nullif(ap->>'Date Submitted','')::timestamptz;
  exception when others then v_submitted := null; end;

  if card is not null and card != '' then
    insert into digest.content_items as ci
      (source, kind, source_id, title, tl_dr, body, occurred_at, url, access_rule, sensitivity, meta)
    values ('application', 'profile', p_id || ':profile', 'Member profile — ' || coalesce(v_name, 'unknown'),
            null, card, now(), null,
            jsonb_build_object('type', 'owner', 'member', p_id), 'normal',
            jsonb_build_object('member', p_id, 'member_name', v_name))
    on conflict (source, source_id) do update set
      title = excluded.title, body = excluded.body, occurred_at = excluded.occurred_at,
      access_rule = excluded.access_rule, meta = excluded.meta, ingested_at = now()
    where ci.title is distinct from excluded.title
       or ci.body is distinct from excluded.body
       or ci.access_rule is distinct from excluded.access_rule
       or ci.meta is distinct from excluded.meta;
  else
    delete from digest.content_items where source = 'application' and source_id = p_id || ':profile';
  end if;

  if answers is not null and answers != '' then
    insert into digest.content_items as ci
      (source, kind, source_id, title, tl_dr, body, occurred_at, url, access_rule, sensitivity, meta)
    values ('application', 'answers', p_id || ':answers', 'Application answers — ' || coalesce(v_name, 'unknown'),
            null, answers, coalesce(v_submitted, now()), null,
            jsonb_build_object('type', 'owner', 'member', p_id), 'normal',
            jsonb_build_object('member', p_id, 'member_name', v_name))
    on conflict (source, source_id) do update set
      title = excluded.title, body = excluded.body, occurred_at = excluded.occurred_at,
      access_rule = excluded.access_rule, meta = excluded.meta, ingested_at = now()
    where ci.title is distinct from excluded.title
       or ci.body is distinct from excluded.body
       or ci.access_rule is distinct from excluded.access_rule
       or ci.meta is distinct from excluded.meta;
  else
    delete from digest.content_items where source = 'application' and source_id = p_id || ':answers';
  end if;
end $function$
